-- Laporan tutup buku November: awal, masuk, dan keluar dari posting; akhir dari saldo_cache
CREATE VIEW tutup_buku AS SELECT b.id, b.nama AS buku,
  COALESCE(SUM(p.jumlah) FILTER (WHERE j.dibuat < '2026-11-01'), 0) AS awal,
  COALESCE(SUM(p.jumlah) FILTER (WHERE j.dibuat >= '2026-11-01' AND p.jumlah > 0), 0) AS masuk,
  COALESCE(-SUM(p.jumlah) FILTER (WHERE j.dibuat >= '2026-11-01' AND p.jumlah < 0), 0) AS keluar,
  b.saldo_cache AS akhir
FROM buku b JOIN posting p ON p.buku_id = b.id JOIN jurnal j ON j.id = p.jurnal_id
GROUP BY b.id;
